// Builds the supplied-source discovery union request from the continued source receipt.
// The source record is embedded unchanged (including absolute provenance paths).
import { readFileSync, writeFileSync } from 'node:fs';
const [sourcePath, outPath] = process.argv.slice(2);
const source = JSON.parse(readFileSync(sourcePath, 'utf8'));
const config = {
  // cms-export and rendered-navigation are expected for the declared scope but were not supplied;
  // they stay as explicit missing-source queue entries.
  expectedSourceIds: ['internal-links', 'cms-export', 'rendered-navigation'],
  scopeComplete: false,
  sources: [source],
};
writeFileSync(outPath, JSON.stringify(config, null, 2) + '\n', { flag: 'wx' });
console.log(JSON.stringify({ written: outPath, records: source.records.length }));

// Builds the campaign config from the discovery request and the discover helper's returned union.
import { readFileSync, writeFileSync } from 'node:fs';
const [requestPath, unionPath, outPath] = process.argv.slice(2);
const discovery = JSON.parse(readFileSync(requestPath, 'utf8'));
const union = JSON.parse(readFileSync(unionPath, 'utf8'));
const config = {
  inputs: union.inputs,
  localRoots: [],
  inventoryComplete: union.inventoryComplete,
  mode: 'full',
  brandName: 'NKSkills',
  network: {
    allowedOrigins: ['https://nkskills.getgroove.me'],
    maxBytes: 10485760,
    timeoutMs: 20000,
    maxRedirects: 5,
    retries: 1,
  },
  maxRunBytes: 100663296,
  discovery,
};
writeFileSync(outPath, JSON.stringify(config, null, 2) + '\n', { flag: 'wx' });
console.log(JSON.stringify({ written: outPath, inputs: config.inputs.length, inventoryComplete: config.inventoryComplete }));

// Inert text inspection of collected content snapshots. Nothing from the target is executed.
// usage: inspect.mjs PART_DIR MODE [uriSubstring]   MODE: head | text | links | robots
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const [part, mode, filter] = process.argv.slice(2);
const jl = (f) => readFileSync(join(part, f), 'utf8').trim().split('\n').map((l) => JSON.parse(l));
const inv = jl('inventory.jsonl').sort((a, b) => a.uri.localeCompare(b.uri));
const ev = jl('evidence.jsonl');
const decode = (s) => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&#x27;/g, "'");
for (const item of inv) {
  if (filter && !item.uri.endsWith(filter)) continue;
  const mine = ev.filter((e) => e.itemId === item.itemId);
  const content = mine.find((e) => e.kind === 'content');
  const html = content.value;
  console.log(`\n===== ${item.uri}  item=${item.itemId.slice(0, 8)} content=${content.evidenceId.slice(0, 8)} bytes=${Buffer.byteLength(html)} lines=${html.split('\n').length}`);
  if (mode === 'robots') {
    for (const e of mine.filter((x) => x.kind === 'crawler-policy')) console.log(JSON.stringify(e.value, null, 1).slice(0, 2500), '\nLIMITS', e.limitations);
    const h = mine.find((x) => x.kind === 'http-response');
    console.log('HTTP', JSON.stringify(h.value, null, 1).slice(0, 1500));
    continue;
  }
  if (mode === 'head') {
    console.log('HTML tag:', (html.match(/<html[^>]*>/i) || [''])[0]);
    const head = (html.match(/<head[\s\S]*?<\/head>/i) || [''])[0];
    for (const m of head.matchAll(/<(title)[^>]*>[\s\S]*?<\/title>|<(meta|link|base)\b[^>]*>/gi)) console.log('  ', m[0].slice(0, 400));
    for (const m of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)) console.log('  SCRIPT attrs=[' + m[1].trim() + '] inlineBytes=' + m[2].length + (/(ld\+json)/.test(m[1]) ? '\n    ' + m[2].slice(0, 3000) : m[2].length ? '\n    ' + m[2].slice(0, 300).replace(/\s+/g, ' ') : ''));
    for (const m of html.matchAll(/<(iframe|template|noscript|form|img|svg|video|audio|picture|canvas)\b[^>]*>/gi)) console.log('  EL', m[0].slice(0, 250));
    for (const m of html.matchAll(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi)) console.log('  H' + m[1], decode(m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()));
    continue;
  }
  if (mode === 'links') {
    const seen = new Map();
    for (const m of html.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi)) {
      const href = (m[1].match(/href="([^"]*)"/i) || [])[1];
      const text = decode(m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
      const rest = m[1].replace(/href="[^"]*"/i, '').replace(/class="[^"]*"/i, '').trim();
      const k = href + ' | ' + text.slice(0, 70) + ' | ' + rest;
      seen.set(k, (seen.get(k) || 0) + 1);
    }
    for (const [k, n] of seen) console.log('  ', n, k);
    continue;
  }
  if (mode === 'text') {
    let body = (html.match(/<body[\s\S]*<\/body>/i) || [html])[0];
    body = body.replace(/<script\b[\s\S]*?<\/script>/gi, ' [script] ').replace(/<style\b[\s\S]*?<\/style>/gi, ' ');
    body = body.replace(/<\/(p|div|li|h[1-6]|section|tr|header|footer|nav|article|pre|dd|dt|summary|details|figcaption|td|th)>/gi, '\n').replace(/<br\s*\/?>/gi, '\n');
    body = body.replace(/<a\b[^>]*href="([^"]*)"[^>]*>/gi, ' [a:$1] ').replace(/<[^>]+>/g, ' ');
    console.log(decode(body).split('\n').map((l) => l.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n'));
  }
}

// Cross-page inert checks over collected snapshots: fragment targets, internal link matrix, locale annotations, robots decisions.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const [part, ...greps] = process.argv.slice(2);
const jl = (f) => readFileSync(join(part, f), 'utf8').trim().split('\n').map((l) => JSON.parse(l));
const inv = jl('inventory.jsonl').sort((a, b) => a.uri.localeCompare(b.uri));
const ev = jl('evidence.jsonl');
const pages = new Map();
for (const item of inv) {
  const mine = ev.filter((e) => e.itemId === item.itemId);
  const http = mine.find((e) => e.kind === 'http-response').value;
  pages.set(item.uri, { item, html: mine.find((e) => e.kind === 'content').value, http, policies: mine.filter((e) => e.kind === 'crawler-policy') });
}
if (greps.length) {
  for (const [uri, p] of pages) for (const g of greps) {
    let i = -1;
    while ((i = p.html.indexOf(g, i + 1)) !== -1) console.log(uri, '@' + i, JSON.stringify(p.html.slice(Math.max(0, i - 220), i + g.length + 260)));
  }
  process.exit(0);
}
const ids = new Map();
for (const [uri, p] of pages) ids.set(uri, new Set([...p.html.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1])));
console.log('--- fragment and internal target checks');
for (const [uri, p] of pages) {
  const base = p.http.finalUrl || uri;
  const out = new Map();
  for (const m of p.html.matchAll(/<a\b[^>]*\shref="([^"]*)"[^>]*>/gi)) {
    let u; try { u = new URL(m[1], base); } catch { console.log('BAD HREF', uri, m[1]); continue; }
    if (u.origin !== 'https://nkskills.getgroove.me') continue;
    const target = u.origin + u.pathname;
    const frag = decodeURIComponent(u.hash.slice(1));
    const known = pages.has(target);
    const fragOk = !frag ? '' : known ? (ids.get(target).has(frag) ? 'frag-ok' : 'FRAG-MISSING') : 'frag-unknown';
    out.set(`${target}${u.hash} ${known ? 'in-inventory' : 'NOT-IN-INVENTORY'} ${fragOk}`, 1);
  }
  console.log(uri); for (const k of out.keys()) console.log('    ', k);
}
console.log('--- inbound internal link counts (distinct source pages)');
for (const [target] of pages) {
  const from = [];
  for (const [uri, p] of pages) {
    const base = p.http.finalUrl || uri;
    for (const m of p.html.matchAll(/<a\b[^>]*\shref="([^"]*)"[^>]*>/gi)) { try { const u = new URL(m[1], base); if (u.origin + u.pathname === target && uri !== target) { from.push(uri.replace('https://nkskills.getgroove.me', '')); break; } } catch {} }
  }
  console.log(target, from.length, from.join(' '));
}
console.log('--- locale annotations');
for (const [uri, p] of pages) {
  const lang = (p.html.match(/<html[^>]*\slang="([^"]*)"/i) || [])[1];
  const canon = (p.html.match(/<link rel="canonical" href="([^"]*)"/i) || [])[1];
  const alts = [...p.html.matchAll(/<link rel="alternate" hreflang="([^"]*)" href="([^"]*)"/gi)].map((m) => m[1] + '=' + m[2].replace('https://nkskills.getgroove.me', ''));
  const robotsMeta = [...p.html.matchAll(/<meta[^>]*name="(robots|googlebot)"[^>]*>/gi)].map((m) => m[0]);
  console.log(uri.replace('https://nkskills.getgroove.me', ''), '| lang', lang, '| canonical', canon, '|', alts.join(' '), '| robotsMeta', robotsMeta.length, '| final', p.http.finalUrl, '| headers', JSON.stringify(p.http.headers));
}
console.log('--- robots policy records');
const seen = new Set();
for (const [uri, p] of pages) for (const e of p.policies) {
  const v = e.value; const key = JSON.stringify([v.status, v.policyText ?? v.body ?? v.text]);
  console.log(uri.replace('https://nkskills.getgroove.me', ''), Object.keys(v).join(','), JSON.stringify(v.decision ?? v.selectedDecision ?? null));
  if (!seen.has(key)) { seen.add(key); console.log(JSON.stringify(v, null, 1).slice(0, 3000)); }
}

// Generates the campaign-review-parts bundle: derived, attributed evidence plus per-item judgments.
// Snapshots are read as inert text. Nothing from the target is executed and nothing is fetched.
// usage: gen-part-review.mjs CAMPAIGN_DIR INDEX_DIR OUT_BUNDLE.json OUT_FACTS.json
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';

const [campaignDir, indexDir, outBundle, outFacts] = process.argv.slice(2);
const sha = (s) => createHash('sha256').update(s).digest('hex');
const ORIGIN = 'https://nkskills.getgroove.me';
const PART = 'parts/000001';
const partDir = join(campaignDir, PART);
const jl = (f) => readFileSync(join(partDir, f), 'utf8').trim().split('\n').map((l) => JSON.parse(l));
const inventory = jl('inventory.jsonl');
const evidence = jl('evidence.jsonl');
const manifestBytes = readFileSync(join(campaignDir, 'campaign.json'));
const manifest = JSON.parse(manifestBytes);
const index = JSON.parse(readFileSync(join(indexDir, 'index.json'), 'utf8'));
const now = new Date().toISOString();
const REVIEWER = 'Claude Fable 5.2 host agent running the content-search-audit skill (automated reviewer; not a human reviewer and not the site owner)';
const short = (u) => u.replace(ORIGIN, '') || '/';
const decode = (s) => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;|&#x27;/g, "'");
const nfc = (s) => s.normalize('NFC');

// ---------- load pages
const pages = new Map();
for (const item of inventory) {
  const mine = evidence.filter((e) => e.itemId === item.itemId);
  const content = mine.find((e) => e.kind === 'content');
  const http = mine.find((e) => e.kind === 'http-response');
  const policies = mine.filter((e) => e.kind === 'crawler-policy');
  if (!content || !http || !policies.length) throw new Error('missing base evidence ' + item.uri);
  const html = content.value;
  const isHtml = /text\/html/.test(http.value.headers['content-type'] || '');
  const finalUrl = http.value.redirects?.length ? new URL(((html.match(/<link rel="canonical" href="([^"]*)"/i) || [])[1]) || item.uri).href : item.uri;
  pages.set(item.uri, { item, content, http, policies, html, isHtml, finalUrl });
}
const P = (path) => { const p = pages.get(ORIGIN + path); if (!p) throw new Error('no page ' + path); return p; };
const kindOf = (uri) => {
  const s = short(uri);
  if (s === '/' || s === '/en/' || s === '/vi/') return 'home';
  if (s.endsWith('/catalog/')) return 'catalog';
  if (s.includes('/solutions/')) return 'solution';
  if (s.includes('/guides/')) return 'guide';
  return 'license-text';
};

// ---------- per page derived facts
function extractText(p) {
  if (!p.isHtml) return p.html;
  let body = (p.html.match(/<body[\s\S]*<\/body>/i) || [p.html])[0];
  body = body.replace(/<script\b[\s\S]*?<\/script>/gi, ' ').replace(/<style\b[\s\S]*?<\/style>/gi, ' ');
  body = body.replace(/<\/(p|div|li|h[1-6]|section|tr|header|footer|nav|article|pre|dd|dt|summary|details|figcaption|td|th|template)>/gi, '\n').replace(/<br\s*\/?>/gi, '\n');
  body = body.replace(/<[^>]+>/g, ' ');
  return decode(body).split('\n').map((l) => l.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n') + '\n';
}
for (const p of pages.values()) {
  p.text = extractText(p);
  p.flat = nfc(p.text.replace(/\s+/g, ' '));
  p.kind = kindOf(p.item.uri);
  p.lang = (p.html.match(/<html[^>]*\slang="([^"]*)"/i) || [])[1] || null;
  p.title = decode((p.html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '') || null;
  p.description = decode((p.html.match(/<meta name="description" content="([^"]*)"/i) || [])[1] || '') || null;
  p.h1 = [...p.html.matchAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi)].map((m) => decode(m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()));
  p.canonical = (p.html.match(/<link rel="canonical" href="([^"]*)"/i) || [])[1] || null;
  p.ogUrl = (p.html.match(/<meta property="og:url" content="([^"]*)"/i) || [])[1] || null;
  p.alternates = [...p.html.matchAll(/<link rel="alternate" hreflang="([^"]*)" href="([^"]*)"/gi)].map((m) => ({ hreflang: m[1], href: m[2] }));
  p.robotsMeta = [...p.html.matchAll(/<meta[^>]*name="(robots|googlebot)"[^>]*>/gi)].map((m) => m[0]);
  p.ids = new Set([...p.html.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1]));
  p.scripts = [...p.html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)].map((m) => ({ src: (m[1].match(/src="([^"]*)"/) || [])[1] || null, type: (m[1].match(/type="([^"]*)"/) || [])[1] || null, inlineBytes: m[2].length }));
  p.anchors = [];
  for (const m of p.html.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi)) {
    const href = (m[1].match(/\shref="([^"]*)"/i) || [])[1];
    if (href === undefined) continue;
    let u; try { u = new URL(decode(href), p.finalUrl); } catch { p.anchors.push({ href, unresolved: true }); continue; }
    p.anchors.push({ href: decode(href), resolved: u.href, origin: u.origin, target: u.origin + u.pathname, fragment: decodeURIComponent(u.hash.slice(1)), text: decode(m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()), ariaLabel: (m[1].match(/aria-label="([^"]*)"/) || [])[1] || null });
  }
}
// "/" is a 308 alias of /en/
const root = P('/'); const en = P('/en/');
if (root.content.snapshotHash !== en.content.snapshotHash) throw new Error('root and /en/ bodies differ; revisit alias judgments');
if (root.http.value.redirects?.[0]?.status !== 308) throw new Error('unexpected root redirect');

// ---------- verified snippets (must occur in the extracted text of the named page)
const need = (p, snippet) => { if (!p.flat.includes(nfc(snippet))) throw new Error(`snippet not found in ${p.item.uri}: ${snippet}`); return snippet; };
const S = {
  enCount: 'Solution Skills 01 technical release 01 evaluation candidate',
  viCount: 'Solution Skills 01 bản kỹ thuật 01 ứng viên đánh giá',
  enCard3: 'EVALUATION CANDIDATE Content search audit',
  viCard3: 'ỨNG VIÊN ĐÁNH GIÁ Content search audit',
  card3Version: 'NK / SOLUTION 003 v0.1.32',
  catCount: '03 Solution Skills',
  catUp: '15 Upstream Skills',
  enCat1: '01 / TECHNICAL RELEASE Codebase onboarding 1.1.0',
  enCat2: '02 / EVALUATION CANDIDATE Problem presentation 0.1.0',
  enCat3: '03 / EVALUATION CANDIDATE Content search audit 0.1.32',
  viCat1: '01 / BẢN PHÁT HÀNH KỸ THUẬT Codebase onboarding 1.1.0',
  viCat2: '02 / ỨNG VIÊN ĐÁNH GIÁ Problem presentation 0.1.0',
  viCat3: '03 / ỨNG VIÊN ĐÁNH GIÁ Content search audit 0.1.32',
  viEyebrow: 'NKSKILLS / DANH MỤ Những skill',
  prereq: 'codegraph, rtk',
  guideAudit: '06 / CONTENT SEARCH AUDIT · 0.1.32',
  enSolPrereq: 'You need the Solution Skill, codegraph, rtk, and a valid CodeGraph index at the repository root.',
  enGuideLinkLabel: 'Read archive and digest verification',
  viGuideLinkLabel: 'Xem quy trình kiểm tra archive và digest',
};
for (const path of ['/', '/en/']) { need(P(path), '02 ' + S.enCount); need(P(path), S.enCard3); need(P(path), S.card3Version); need(P(path), 'TECHNICAL RELEASE Codebase onboarding'); need(P(path), 'EVALUATION CANDIDATE Problem presentation'); }
need(P('/vi/'), '02 ' + S.viCount); need(P('/vi/'), S.viCard3); need(P('/vi/'), S.card3Version); need(P('/vi/'), 'BẢN PHÁT HÀNH KỸ THUẬT Codebase onboarding'); need(P('/vi/'), 'ỨNG VIÊN ĐÁNH GIÁ Problem presentation');
for (const k of ['catCount', 'catUp', 'enCat1', 'enCat2', 'enCat3']) need(P('/en/catalog/'), S[k]);
for (const k of ['catCount', 'catUp', 'viCat1', 'viCat2', 'viCat3', 'viEyebrow']) need(P('/vi/catalog/'), S[k]);
for (const path of ['/en/guides/codex/', '/en/guides/claude-code/']) { need(P(path), S.prereq); need(P(path), S.guideAudit); need(P(path), S.enGuideLinkLabel); }
for (const path of ['/vi/guides/codex/', '/vi/guides/claude-code/']) { need(P(path), S.prereq); need(P(path), S.guideAudit); need(P(path), S.viGuideLinkLabel); }
need(P('/en/solutions/codebase-onboarding/'), S.enSolPrereq);
if (P('/vi/').flat.includes('NKSKILLS / DANH MỤ ') ) throw new Error('unexpected truncated eyebrow on vi home');

// ---------- cross-page computations
const linkGraph = (p) => {
  const internal = new Map(); const external = new Set();
  for (const a of p.anchors) {
    if (a.unresolved) continue;
    if (a.origin !== ORIGIN) { external.add(a.resolved); continue; }
    const t = pages.get(a.target);
    const key = a.target + '#' + a.fragment;
    if (!internal.has(key)) internal.set(key, { target: a.target, fragment: a.fragment || null, inInventory: Boolean(t), capturedStatus: t ? t.http.value.status : null, fragmentResolvedInTargetSnapshot: a.fragment ? (t ? t.ids.has(a.fragment) : null) : null, anchorTexts: [] });
    const row = internal.get(key); const label = a.text || a.ariaLabel || '';
    if (label && !row.anchorTexts.includes(label)) row.anchorTexts.push(label);
  }
  const inbound = [...pages.values()].filter((q) => q !== p && q.anchors.some((a) => a.target === p.item.uri)).map((q) => q.item.uri).sort();
  return { page: p.item.uri, surface: 'raw HTML source anchors (a[href]) only; scripts not executed', internalTargets: [...internal.values()], externalTargets: { count: external.size, note: 'Outside the single allowed origin; not fetched, reachability unverified', urls: [...external].sort() }, inboundFromCollectedPages: inbound };
};
for (const p of pages.values()) p.graph = linkGraph(p);
const brokenInternal = [...pages.values()].flatMap((p) => p.graph.internalTargets.filter((t) => !t.inInventory || t.capturedStatus !== 200 || t.fragmentResolvedInTargetSnapshot === false).map((t) => p.item.uri + ' -> ' + t.target));
if (brokenInternal.length) throw new Error('unexpected unresolved internal targets: ' + brokenInternal.join(', '));

const localeMap = (p) => {
  if (!p.isHtml) return { page: p.item.uri, htmlLang: null, alternates: [], note: 'text/plain resource; no HTML locale annotations. Retained response headers: ' + Object.keys(p.http.value.headers).join(', ') };
  const self = p.finalUrl;
  const rows = p.alternates.map((a) => {
    const t = pages.get(a.href);
    return { ...a, targetInInventory: Boolean(t), targetStatus: t ? t.http.value.status : null, targetHtmlLang: t ? t.lang : null, targetListsSameAlternateSet: t ? JSON.stringify(t.alternates) === JSON.stringify(p.alternates) : null, targetCanonicalIsSelf: t ? t.canonical === a.href : null };
  });
  const selfRow = rows.find((r) => r.href === self);
  return { page: p.item.uri, effectiveUrl: self, htmlLang: p.lang, canonical: p.canonical, alternates: rows, selfReferenceHreflang: selfRow ? selfRow.hreflang : null, allReciprocal: rows.every((r) => r.targetInInventory && r.targetStatus === 200 && r.targetListsSameAlternateSet && r.targetCanonicalIsSelf), langMatches: rows.filter((r) => r.hreflang !== 'x-default').every((r) => r.targetHtmlLang === r.hreflang) };
};
for (const p of pages.values()) { p.locale = localeMap(p); if (p.isHtml && !(p.locale.allReciprocal && p.locale.langMatches && p.locale.selfReferenceHreflang === p.lang && p.alternates.length === 3)) throw new Error('locale annotations not clean for ' + p.item.uri); }

const canonicalTargets = (p) => {
  if (!p.isHtml) return { page: p.item.uri, declaredCanonical: null, note: 'text/plain resource; no HTML canonical element. Retained response headers: ' + Object.keys(p.http.value.headers).join(', ') + ' (selected subset; a Link header cannot be ruled out from this record alone)' };
  const t = pages.get(p.canonical);
  return { page: p.item.uri, requestedUrl: p.item.uri, redirects: p.http.value.redirects ?? [], effectiveUrl: p.finalUrl, declaredCanonical: p.canonical, canonicalEqualsEffectiveUrl: p.canonical === p.finalUrl, ogUrl: p.ogUrl, ogUrlEqualsCanonical: p.ogUrl === p.canonical, canonicalTargetInInventory: Boolean(t), canonicalTargetStatus: t ? t.http.value.status : null, canonicalTargetDeclaresItself: t ? t.canonical === p.canonical : null, hreflangSelfEntryEqualsCanonical: p.alternates.some((a) => a.href === p.canonical && a.hreflang === p.lang) };
};
for (const p of pages.values()) { p.canon = canonicalTargets(p); if (p.isHtml && !(p.canon.canonicalEqualsEffectiveUrl && p.canon.ogUrlEqualsCanonical && p.canon.canonicalTargetStatus === 200 && p.canon.canonicalTargetDeclaresItself && p.canon.hreflangSelfEntryEqualsCanonical)) throw new Error('canonical signals not clean for ' + p.item.uri); }

const mediaInventory = (p) => {
  if (!p.isHtml) return { page: p.item.uri, elements: [], note: 'text/plain resource; no media elements' };
  const els = [];
  for (const m of p.html.matchAll(/<(img|svg|video|audio|picture|canvas|iframe|object|embed)\b[^>]*>/gi)) els.push({ element: m[1].toLowerCase(), tag: m[0] });
